class Solution {
  public int[] maximumSubarrayXor(int[] nums, int[][] queries) {
    int n = nums.length;
    int[][] score = new int[n][n];
    for (int i = 0; i < n; i++) score[i][i] = nums[i];
    for (int len = 2; len <= n; len++)
      for (int i = 0; i + len <= n; i++) {
        int j = i + len - 1;
        score[i][j] = score[i][j - 1] ^ score[i + 1][j];
      }
    int[][] best = new int[n][n];
    for (int i = 0; i < n; i++) best[i][i] = score[i][i];
    for (int len = 2; len <= n; len++)
      for (int i = 0; i + len <= n; i++) {
        int j = i + len - 1;
        best[i][j] = Math.max(score[i][j], Math.max(best[i + 1][j], best[i][j - 1]));
      }
    int[] ans = new int[queries.length];
    for (int q = 0; q < queries.length; q++) ans[q] = best[queries[q][0]][queries[q][1]];
    return ans;
  }
}
